// Deployable copy of the pure engine projection, without imports outside the function.
import { rolldown } from 'rolldown';
import { writeFile } from 'node:fs/promises';
const bundle = await rolldown({ input: 'src/engine/crunningStrength.ts', platform: 'neutral' });
const { output } = await bundle.generate({ format: 'esm' });
await writeFile(
  'supabase/functions/troca-crunning/engine.generated.ts',
  '// @ts-nocheck\n// Generated by node scripts/build-crunning-engine.mjs. Do not edit.\n' +
    output[0].code,
);
await bundle.close();
